package model

import (
	"time"

	"github.com/choysum-dev/choysum/pkg/meta"
)

// IrLockLease provides a DB-agnostic mutual exclusion primitive.
// It is intentionally simple to support Postgres/MySQL/SQLite via GORM.
//
// Resource should be globally unique (uniqueIndex) to represent one lock.
// ExpiresAt enables lease semantics to recover from crashed owners.
// OwnerId is an opaque identifier generated by the caller.
//
// NOTE: Acquire/Renew/Release logic lives in internal/state/lease.
type IrLockLease struct {
	meta.BaseModel
	Resource  string `gorm:"uniqueIndex"`
	OwnerId   string
	ExpiresAt time.Time `gorm:"index"`
}

func (l *IrLockLease) TableName() string {
	return "meta_ir_lock_lease"
}
